def fun(sequence, algo='bubble'):
    def bubble_sort(arr):
        n = len(arr)
        for i in range(n):
            for j in range(0, n-i-1):
                if arr[j] > arr[j+1]:
                    arr[j], arr[j+1] = arr[j+1], arr[j]
        return arr

    def quick_sort(arr):
        if len(arr) <= 1:
            return arr
        else:
            pivot = arr[0]
            less, equal, greater = [], [pivot], []
            for x in arr[1:]:
                if x < pivot:
                    less.append(x)
                elif x == pivot:
                    equal.append(x)
                else:
                    greater.append(x)
            return quick_sort(less) + equal + quick_sort(greater)

    sort_algorithms = {
        'bubble': bubble_sort,
        'quick': quick_sort
    }

    return sort_algorithms.get(algo, bubble_sort)(sequence)

